    WHEN 'tenancy.data_check' THEN table_name IN ('Location', 'Membership', 'MembershipLocationScope', 'Reward', 'RewardImage', 'RewardLocationScope', 'RewardRedemption', 'RewardSale', 'TenantApiKey', 'TenantInvitationLocationScope', 'TenantTerminal')
    WHEN 'tenancy.default_tenant.verify' THEN table_name IN ('Tenant')
    WHEN 'tenancy.flag_facts.read' THEN table_name IN ('Membership', 'MembershipLocationScope')
    WHEN 'tenant.access_request.create' THEN table_name IN ('Membership', 'TenantAccessRequest', 'TenantAuditLog')
    WHEN 'tenant.access_request.review' THEN table_name IN ('Location', 'Membership', 'MembershipLocationScope', 'Role', 'TenantAccessRequest', 'TenantAuditLog')
    WHEN 'tenant.context.list_memberships' THEN table_name IN ('Membership', 'Tenant', 'TenantMerchantProfile')
    WHEN 'tenant.context.location_access' THEN table_name IN ('Location')
    WHEN 'tenant.context.resolve_membership' THEN table_name IN ('Tenant', 'TenantMerchantProfile')
    WHEN 'tenant.context.resolve_route_key' THEN table_name IN ('Membership', 'MembershipLocationScope', 'Tenant', 'TenantSlugHistory')
    WHEN 'tenant.customer_ban.create' THEN table_name IN ('Reward', 'RewardClaim', 'RewardRedemption', 'TenantAuditLog', 'TenantCustomerBan')
    WHEN 'tenant.customer_ban.lift' THEN table_name IN ('TenantAuditLog', 'TenantCustomerBan')
    WHEN 'tenant.customer_ban.read' THEN table_name IN ('Reward', 'RewardClaim', 'RewardRedemption', 'TenantCustomerBan', 'User')
    WHEN 'tenant.display_data.read' THEN table_name IN ('FileVariant', 'Membership', 'StoredFile', 'Tenant', 'TenantAsset')
    WHEN 'tenant.enumerate' THEN table_name IN ('Tenant')
    WHEN 'tenant.invitation.accept_merchant_onboarding' THEN table_name IN ('Location', 'Membership', 'MembershipLocationScope', 'PermissionAuditLog', 'Role', 'SignupReferralCode', 'Tenant', 'TenantAuditLog', 'TenantInvitation', 'TenantInvitationLocationScope', 'TenantLifecycleEvent', 'TenantMerchantProfile', 'User', 'UserPermission', 'UserRole')
    WHEN 'tenant.invitation.create' THEN table_name IN ('EmailLog', 'Location', 'Membership', 'OutboxEvent', 'TenantAuditLog', 'TenantInvitation', 'TenantInvitationLocationScope', 'User')
    WHEN 'tenant.invitation.register_and_accept' THEN table_name IN ('Membership', 'MembershipLocationScope', 'PermissionAuditLog', 'Role', 'SignupReferralCode', 'Tenant', 'TenantAuditLog', 'TenantInvitation', 'TenantInvitationLocationScope', 'User', 'UserPermission', 'UserRole')
    WHEN 'tenant.invitation.resolve_token' THEN table_name IN ('Location', 'Tenant', 'TenantInvitation', 'TenantInvitationLocationScope', 'TenantMerchantProfile', 'User')
    WHEN 'tenant.invitation.revoke' THEN table_name IN ('TenantAuditLog', 'TenantInvitation', 'TenantInvitationLocationScope')
    WHEN 'tenant.invitation.submit_onboarding_documents' THEN table_name IN ('StoredFile', 'Tenant', 'TenantAuditLog', 'TenantInvitation', 'TenantInvitationLocationScope', 'TenantKybFile', 'TenantMerchantProfile')
    WHEN 'tenant.kyb.admin_decide' THEN table_name IN ('Tenant', 'TenantAuditLog', 'TenantMerchantProfile')
    WHEN 'tenant.lifecycle.admin_ban' THEN table_name IN ('Tenant', 'TenantAuditLog', 'TenantLifecycleEvent', 'TenantSuspensionAppeal')
    WHEN 'tenant.lifecycle.admin_reinstate' THEN table_name IN ('Tenant', 'TenantAuditLog', 'TenantLifecycleEvent', 'TenantSuspensionAppeal')
    WHEN 'tenant.lifecycle.admin_reject_appeal' THEN table_name IN ('TenantAuditLog', 'TenantSuspensionAppeal')
    WHEN 'tenant.lifecycle.admin_suspend' THEN table_name IN ('Tenant', 'TenantAuditLog', 'TenantLifecycleEvent')
    WHEN 'tenant.lifecycle.admin_unban' THEN table_name IN ('Tenant', 'TenantAuditLog', 'TenantLifecycleEvent')
    WHEN 'tenant.lifecycle.appeal' THEN table_name IN ('Tenant', 'TenantAuditLog', 'TenantSuspensionAppeal')
    WHEN 'tenant.lifecycle.reactivate' THEN table_name IN ('Membership', 'Tenant', 'TenantAuditLog', 'TenantLifecycleEvent', 'TenantSlugHistory')
    WHEN 'tenant.lifecycle.read' THEN table_name IN ('Membership', 'Tenant', 'TenantLifecycleEvent', 'TenantSlugHistory', 'TenantSuspensionAppeal', 'User')
    WHEN 'tenant.location.admin_create' THEN table_name IN ('Location', 'Tenant', 'TenantAuditLog', 'TenantMerchantProfile')
    WHEN 'tenant.location.admin_list' THEN table_name IN ('Location', 'Tenant')
    WHEN 'tenant.location.admin_review' THEN table_name IN ('Location', 'TenantAuditLog')
    WHEN 'tenant.location.close' THEN table_name IN ('Location', 'MembershipLocationScope', 'TenantApiKey', 'TenantAuditLog', 'TenantTerminal')
    WHEN 'tenant.membership.accept' THEN table_name IN ('Membership', 'MembershipLocationScope', 'Role', 'Tenant', 'TenantAuditLog', 'TenantInvitation', 'TenantInvitationLocationScope')
    WHEN 'tenant.membership.leave' THEN table_name IN ('Membership', 'MembershipLocationScope', 'Tenant', 'TenantAuditLog', 'TenantSlugHistory')
    WHEN 'tenant.membership.remove_from_location' THEN table_name IN ('Membership', 'MembershipLocationScope', 'TenantAuditLog')
    WHEN 'tenant.membership.rename_own' THEN table_name IN ('Membership', 'MembershipLocationScope', 'TenantAuditLog')
    WHEN 'tenant.membership.roster' THEN table_name IN ('User')
    WHEN 'tenant.merchant.admin_read' THEN table_name IN ('Location', 'Membership', 'StoredFile', 'Tenant', 'TenantKybFile', 'TenantMerchantProfile', 'User')
    WHEN 'tenant.onboarding.document_file' THEN table_name IN ('StoredFile')
    WHEN 'tenant.provision.admin_merchant_invite' THEN table_name IN ('AuthorizationAudit', 'EmailLog', 'OutboxEvent', 'Role', 'RolePermission', 'Tenant', 'TenantAuditLog', 'TenantInvitation', 'TenantLifecycleEvent', 'TenantMerchantProfile', 'TenantPlacement', 'TenantSlugHistory')
    WHEN 'tenant.provision.platform_invite' THEN table_name IN ('AuthorizationAudit', 'Role', 'RolePermission', 'Tenant', 'TenantAuditLog', 'TenantInvitation', 'TenantLifecycleEvent', 'TenantMerchantProfile', 'TenantPlacement')
    WHEN 'tiers.settings.write' THEN table_name IN ('CustomerTierSettings', 'User')
    WHEN 'tiers.standing.evaluate' THEN table_name IN ('CustomerTierChange', 'CustomerTierSettings', 'CustomerTierStanding', 'Membership', 'Notification', 'RewardRedemption')
    WHEN 'tiers.standing.read' THEN table_name IN ('CustomerTierChange', 'CustomerTierSettings', 'CustomerTierStanding', 'Membership', 'RewardRedemption', 'Tenant', 'TenantCustomer', 'User')
    WHEN 'webhooks.inbound.read' THEN table_name IN ('ReceivedWebhook')
    WHEN 'webhooks.inbound.record' THEN table_name IN ('ReceivedWebhook')
    WHEN 'webhooks.outbound.deliver' THEN table_name IN ('Membership', 'Notification', 'Tenant', 'WebhookDelivery', 'WebhookEndpoint', 'WebhookEvent')
    WHEN 'webhooks.outbound.retention' THEN table_name IN ('WebhookDelivery', 'WebhookEvent')
    WHEN 'webhooks.outbound.sweep' THEN table_name IN ('WebhookDelivery', 'WebhookEndpoint', 'WebhookEvent')
    ELSE false
  END;
END;
$$;

COMMENT ON FUNCTION app_rls_bypass_on(text) IS
  'ADR 012: true only when the session runs an allowlisted system operation whose registry scope lists table_name.';

-- app_member_of: The user has an active membership in the tenant; when the session names a tenant, only that tenant.
CREATE OR REPLACE FUNCTION app_member_of(org_id text) RETURNS boolean
LANGUAGE sql
STABLE
SECURITY DEFINER
SET search_path = public
AS $$
  SELECT app_current_user_id() IS NOT NULL
    -- A session bound to a tenant (a tenant route) is confined to it: a member of tenants A and B
    -- working on A's route reaches only A's rows. Tenantless sessions (listing one's memberships,
    -- choosing a tenant) still see every tenant they belong to. Multi-tenancy plan D10, ADR 062.
    AND (app_current_tenant_id() IS NULL OR app_current_tenant_id() = org_id)
    AND EXISTS (
      SELECT 1 FROM public."Membership" m
      WHERE m."tenantId" = org_id
        AND m."userId" = app_current_user_id()
        AND m.status = 'ACTIVE'
        AND m."isDeleted" = false
    );
$$;

COMMENT ON FUNCTION app_member_of(text) IS
  'ReBAC: user has an active membership in the tenant; when the session names a tenant, only that tenant.';

-- app_tenant_member_of: The session is bound to this tenant and its user is an active member (fails closed without a tenant).
CREATE OR REPLACE FUNCTION app_tenant_member_of(org_id text) RETURNS boolean
LANGUAGE sql
STABLE
SECURITY DEFINER
SET search_path = public
AS $$
  SELECT app_current_user_id() IS NOT NULL
    AND app_current_tenant_id() IS NOT NULL
    AND app_current_tenant_id() = org_id
    AND EXISTS (
      SELECT 1 FROM public."Membership" m
      WHERE m."tenantId" = org_id
        AND m."userId" = app_current_user_id()
        AND m.status = 'ACTIVE'
        AND m."isDeleted" = false
    );
$$;

COMMENT ON FUNCTION app_tenant_member_of(text) IS
  'ReBAC: active tenant session org matches row org and user is a member (fail-closed).';

-- app_tenant_org_member: A member of the tenant: through the bound tenant when the session has one, otherwise any active membership.
CREATE OR REPLACE FUNCTION app_tenant_org_member(org_id text) RETURNS boolean
LANGUAGE sql
STABLE
AS $$
  SELECT app_tenant_member_of(org_id)
    OR app_member_of(org_id);
$$;

COMMENT ON FUNCTION app_tenant_org_member(text) IS
  'ReBAC: tenant-scoped org member when session org is set; otherwise legacy membership check.';

-- app_tenant_has_location_access: The session's user may work at this store of the bound tenant (all stores, or this one selected).
CREATE OR REPLACE FUNCTION app_tenant_has_location_access(loc_id text) RETURNS boolean
LANGUAGE sql
STABLE
SECURITY DEFINER
SET search_path = public
AS $$
  SELECT (
      app_current_user_id() IS NOT NULL
      AND app_current_tenant_id() IS NOT NULL
      AND EXISTS (
        SELECT 1
        FROM public."Location" loc
        INNER JOIN public."Membership" m
          ON m."tenantId" = loc."tenantId"
         AND m."userId" = app_current_user_id()
         AND m.status = 'ACTIVE'
         AND m."isDeleted" = false
        WHERE loc.id = loc_id
          AND loc."tenantId" = app_current_tenant_id()
          AND (
            EXISTS (
              SELECT 1
              FROM public."MembershipLocationScope" s
              WHERE s."membershipId" = m.id
                AND s."isDeleted" = false
                AND s."scopeType" = 'ALL_LOCATIONS'
            )
            OR EXISTS (
              SELECT 1
              FROM public."MembershipLocationScope" s
              WHERE s."membershipId" = m.id
                AND s."isDeleted" = false
                AND s."scopeType" = 'SELECTED'
                AND s."locationId" = loc_id
            )
          )
      )
    );
$$;

COMMENT ON FUNCTION app_tenant_has_location_access(text) IS
  'ACL: session user may access the location within app.current_tenant_id.';

-- app_tenant_row_org_location_access: The row is the bound tenant's and the user may work at the row's store.
CREATE OR REPLACE FUNCTION app_tenant_row_org_location_access(
  row_tenant_id text,
  row_location_id text
) RETURNS boolean
LANGUAGE sql
STABLE
AS $$
  SELECT app_current_tenant_id() IS NOT NULL
    AND row_tenant_id = app_current_tenant_id()
    AND app_tenant_has_location_access(row_location_id);
$$;

COMMENT ON FUNCTION app_tenant_row_org_location_access(text, text) IS
  'ACL: row org matches session org and user has location scope for row location.';

-- app_tenant_org_optional_location_access: A member of the row's tenant; when the row names a store, the user must also have that store.
CREATE OR REPLACE FUNCTION app_tenant_org_optional_location_access(
  row_tenant_id text,
  row_location_id text
) RETURNS boolean
LANGUAGE sql
STABLE
AS $$
  SELECT app_tenant_org_member(row_tenant_id)
    AND (
      row_location_id IS NULL
      OR row_location_id = ''
      OR app_tenant_has_location_access(row_location_id)
    );
$$;

COMMENT ON FUNCTION app_tenant_org_optional_location_access(text, text) IS
  'ReBAC + ACL: org member; when "locationId" is set, user must have branch ACL.';

-- app_has_permission: The ROLE and GRANT allow paths: the caller's role or a live grant gives resource.action in the tenant, at the store.
CREATE OR REPLACE FUNCTION app_has_permission(want_resource text, want_action text, org_id text, loc_id text) RETURNS boolean
LANGUAGE sql
STABLE
SECURITY DEFINER
SET search_path = public
AS $$
  WITH member AS (
    SELECT m.id, m."roleId"
    FROM public."Membership" m
    WHERE app_current_user_id() IS NOT NULL
      AND (app_current_tenant_id() IS NULL OR app_current_tenant_id() = org_id)
      AND m."tenantId" = org_id
      AND m."userId" = app_current_user_id()
      AND m.status = 'ACTIVE'
      AND m."isDeleted" = false
  ),
  -- The membership's stores cover the record (a deleted store drops out of the scope).
  covered AS (
    SELECT 1 FROM member
    WHERE loc_id IS NULL
       OR EXISTS (
         SELECT 1 FROM public."MembershipLocationScope" s
         LEFT JOIN public."Location" l ON l.id = s."locationId"
         WHERE s."membershipId" = member.id
           AND s."isDeleted" = false
           AND (s."scopeType" = 'ALL_LOCATIONS' OR (s."locationId" = loc_id AND l."isDeleted" = false))
       )
  ),
  -- The exact verb asked for: there is no catch-all action (as `permissionSatisfies`).
  wanted AS (
    SELECT p.id FROM public."Permission" p
    WHERE p."isDeleted" = false
      AND p.scope NOT IN ('OWN', 'RESOURCE')
      AND p.resource::text = want_resource
      AND p.action::text = want_action
  )
  SELECT EXISTS (SELECT 1 FROM covered) AND (
    EXISTS (
      SELECT 1 FROM member
      JOIN public."Role" r ON r.id = member."roleId"
      JOIN public."RolePermission" rp ON rp."roleId" = r.id
      WHERE r."isDeleted" = false AND r."isActive" = true AND r.kind = 'TENANT' AND r."tenantId" = org_id
        AND rp."isDeleted" = false
        AND rp."permissionId" IN (SELECT id FROM wanted)
    )
    OR EXISTS (
      SELECT 1 FROM public."UserPermission" g
      LEFT JOIN public."Location" l ON l.id = g."locationId"
      WHERE g."userId" = app_current_user_id()
        AND g."tenantId" = org_id
        AND g.effect = 'ALLOW'
        AND g."isDeleted" = false
        AND (g."expiresAt" IS NULL OR g."expiresAt" > (EXTRACT(epoch FROM now()) * 1000)::bigint)
        AND g."permissionId" IN (SELECT id FROM wanted)
        -- A store-limited grant reaches only that store, never a tenant-level record.
        AND (g."locationId" IS NULL OR (g."locationId" = loc_id AND l."isDeleted" = false))
    )
  );
$$;

COMMENT ON FUNCTION app_has_permission(text, text, text, text) IS
  'ADR 067: the caller''s role or a live grant gives resource.action in the tenant, at the store (NULL: tenant-level).';

-- app_permitted_tenants: Every tenant where the caller may do resource.action on a tenant-level record: app_has_permission(…, tenant, NULL) for all tenants at once, so a policy asks once per statement, not once per row.
CREATE OR REPLACE FUNCTION app_permitted_tenants(want_resource text, want_action text) RETURNS text[]
LANGUAGE sql
STABLE
SECURITY DEFINER
SET search_path = public
AS $$
  WITH member AS (
    SELECT m.id, m."roleId", m."tenantId"
    FROM public."Membership" m
    WHERE app_current_user_id() IS NOT NULL
      AND (app_current_tenant_id() IS NULL OR app_current_tenant_id() = m."tenantId")
      AND m."userId" = app_current_user_id()
      AND m.status = 'ACTIVE'
      AND m."isDeleted" = false
  ),
  wanted AS (
    SELECT p.id FROM public."Permission" p
    WHERE p."isDeleted" = false
      AND p.scope NOT IN ('OWN', 'RESOURCE')
      AND p.resource::text = want_resource
      AND p.action::text = want_action
  ),
  by_role AS (
    SELECT member."tenantId" FROM member
    JOIN public."Role" r ON r.id = member."roleId"
    JOIN public."RolePermission" rp ON rp."roleId" = r.id
    WHERE r."isDeleted" = false AND r."isActive" = true AND r.kind = 'TENANT' AND r."tenantId" = member."tenantId"
      AND rp."isDeleted" = false
      AND rp."permissionId" IN (SELECT id FROM wanted)
  ),
  -- A store-limited grant never reaches a tenant-level record.
  by_grant AS (
    SELECT member."tenantId" FROM member
    JOIN public."UserPermission" g ON g."tenantId" = member."tenantId"
    WHERE g."userId" = app_current_user_id()
      AND g.effect = 'ALLOW'
      AND g."isDeleted" = false
      AND (g."expiresAt" IS NULL OR g."expiresAt" > (EXTRACT(epoch FROM now()) * 1000)::bigint)
      AND g."permissionId" IN (SELECT id FROM wanted)
      AND g."locationId" IS NULL
  )
  SELECT coalesce(array_agg(DISTINCT allowed."tenantId"), ARRAY[]::text[])
  FROM (SELECT "tenantId" FROM by_role UNION SELECT "tenantId" FROM by_grant) AS allowed;
$$;

COMMENT ON FUNCTION app_permitted_tenants(text, text) IS
  'ADR 090: the tenants where the caller''s role or a live tenant-wide grant gives resource.action (tenant-level records); one call per statement.';

-- app_permitted_stores: Every store where the caller may do resource.action, as 'tenant|store' keys ('tenant|*' for every store of a tenant): app_has_permission(…, tenant, store) for all stores at once, asked once per statement.
CREATE OR REPLACE FUNCTION app_permitted_stores(want_resource text, want_action text) RETURNS text[]
LANGUAGE sql
STABLE
SECURITY DEFINER
SET search_path = public
AS $$
  WITH member AS (
    SELECT m.id, m."roleId", m."tenantId"
    FROM public."Membership" m
    WHERE app_current_user_id() IS NOT NULL
      AND (app_current_tenant_id() IS NULL OR app_current_tenant_id() = m."tenantId")
      AND m."userId" = app_current_user_id()
      AND m.status = 'ACTIVE'
      AND m."isDeleted" = false
  ),
  -- The stores each membership covers: '*' for all of them, otherwise each live selected store.
  covered AS (
    SELECT member.id AS membership_id, member."tenantId", '*'::text AS store
    FROM member
    WHERE EXISTS (
      SELECT 1 FROM public."MembershipLocationScope" s
      WHERE s."membershipId" = member.id AND s."isDeleted" = false AND s."scopeType" = 'ALL_LOCATIONS'
    )
    UNION
    SELECT member.id, member."tenantId", s."locationId"
    FROM member
    JOIN public."MembershipLocationScope" s ON s."membershipId" = member.id
    JOIN public."Location" l ON l.id = s."locationId"
    WHERE s."isDeleted" = false AND s."scopeType" = 'SELECTED' AND l."isDeleted" = false
  ),
  wanted AS (
    SELECT p.id FROM public."Permission" p
    WHERE p."isDeleted" = false
      AND p.scope NOT IN ('OWN', 'RESOURCE')
      AND p.resource::text = want_resource
      AND p.action::text = want_action
  ),
  -- The role, or a tenant-wide grant, gives it at every store the membership covers.
  tenant_wide AS (
    SELECT member.id AS membership_id FROM member
    JOIN public."Role" r ON r.id = member."roleId"
    JOIN public."RolePermission" rp ON rp."roleId" = r.id
    WHERE r."isDeleted" = false AND r."isActive" = true AND r.kind = 'TENANT' AND r."tenantId" = member."tenantId"
      AND rp."isDeleted" = false
      AND rp."permissionId" IN (SELECT id FROM wanted)
    UNION
    SELECT member.id FROM member
    JOIN public."UserPermission" g ON g."tenantId" = member."tenantId"
    WHERE g."userId" = app_current_user_id()
      AND g.effect = 'ALLOW'
      AND g."isDeleted" = false
      AND (g."expiresAt" IS NULL OR g."expiresAt" > (EXTRACT(epoch FROM now()) * 1000)::bigint)
      AND g."permissionId" IN (SELECT id FROM wanted)
      AND g."locationId" IS NULL
  ),
  -- A store-limited grant gives it at that live store, when the membership covers it.
  store_grants AS (
    SELECT covered."tenantId", g."locationId" AS store
    FROM covered
    JOIN public."UserPermission" g ON g."tenantId" = covered."tenantId"
    JOIN public."Location" l ON l.id = g."locationId"
    WHERE g."userId" = app_current_user_id()
      AND g.effect = 'ALLOW'
      AND g."isDeleted" = false
      AND (g."expiresAt" IS NULL OR g."expiresAt" > (EXTRACT(epoch FROM now()) * 1000)::bigint)
      AND g."permissionId" IN (SELECT id FROM wanted)
      AND l."isDeleted" = false
      AND (covered.store = '*' OR covered.store = g."locationId")
  )
  SELECT coalesce(array_agg(DISTINCT allowed.key), ARRAY[]::text[])
  FROM (
    SELECT covered."tenantId" || '|' || covered.store AS key FROM covered JOIN tenant_wide ON tenant_wide.membership_id = covered.membership_id
    UNION
    SELECT store_grants."tenantId" || '|' || store_grants.store FROM store_grants
  ) AS allowed;
$$;

COMMENT ON FUNCTION app_permitted_stores(text, text) IS
  'ADR 090: the stores where the caller''s role or a live grant gives resource.action, as tenant|store keys (tenant|* = every store); one call per statement.';

-- app_shared: The SHARE allow path: one record shared with the caller's active membership, at the level or higher.
CREATE OR REPLACE FUNCTION app_shared(want_resource text, record_id text, want_level text) RETURNS boolean
LANGUAGE sql
STABLE
SECURITY DEFINER
SET search_path = public
AS $$
  SELECT app_current_user_id() IS NOT NULL AND EXISTS (
    SELECT 1 FROM public."ResourceAcl" a
    JOIN public."Membership" m ON m.id = a."membershipId"
    WHERE a."resourceType" = want_resource
      AND a."resourceId" = record_id
      AND a."isDeleted" = false
      AND (a."expiresAt" IS NULL OR a."expiresAt" > (EXTRACT(epoch FROM now()) * 1000)::bigint)
      AND (a.level::text = want_level OR a.level = 'EDIT')
      AND m."userId" = app_current_user_id()
      AND m.status = 'ACTIVE'
      AND m."isDeleted" = false
      AND (app_current_tenant_id() IS NULL OR app_current_tenant_id() = m."tenantId")
  );
$$;

COMMENT ON FUNCTION app_shared(text, text, text) IS
  'ADR 067: one record shared with the caller''s active membership, at the level or higher (EDIT includes VIEW).';

-- app_holds_reward_claim: The session's user holds a (non-deleted) claim on the reward, so the reward stays readable to them after it stops being public. SECURITY DEFINER so it reads claims without re-entering that table's policies (one of which reads rewards: a policy cycle).
CREATE OR REPLACE FUNCTION app_holds_reward_claim("rewardId" text) RETURNS boolean
LANGUAGE sql STABLE SECURITY DEFINER SET search_path = public AS $$
  SELECT app_current_user_id() IS NOT NULL
    AND EXISTS (
      SELECT 1 FROM public."RewardClaim" c
      WHERE c."rewardId" = app_holds_reward_claim."rewardId"
        AND c."userId" = app_current_user_id()
        AND c."isDeleted" = false
    );
$$;

-- app_current_api_key_id: The verified API key of the session, or NULL.
CREATE OR REPLACE FUNCTION app_current_api_key_id() RETURNS text
LANGUAGE sql STABLE AS $$
  SELECT NULLIF(current_setting('app.current_api_key_id', true), '');
$$;

-- app_current_api_key_location_id: The store a store-scoped key is limited to, or NULL for a tenant-wide key.
CREATE OR REPLACE FUNCTION app_current_api_key_location_id() RETURNS text
LANGUAGE sql STABLE AS $$
  SELECT NULLIF(current_setting('app.current_api_key_location_id', true), '');
$$;

-- app_api_key_org_access: The session is an API key acting for this tenant.
CREATE OR REPLACE FUNCTION app_api_key_org_access(org_id text) RETURNS boolean
LANGUAGE sql STABLE AS $$
  SELECT app_current_api_key_id() IS NOT NULL
    AND app_current_tenant_id() IS NOT NULL
    AND org_id = app_current_tenant_id();
$$;

-- app_api_key_store_access: An API key of this tenant and, for a store-scoped key, the row belongs to the key's store (a row with no store: tenant-wide keys only).
CREATE OR REPLACE FUNCTION app_api_key_store_access(org_id text, loc_id text) RETURNS boolean
LANGUAGE sql STABLE AS $$
  SELECT app_api_key_org_access(org_id)
    AND (app_current_api_key_location_id() IS NULL OR loc_id = app_current_api_key_location_id());
$$;

-- app_api_key_reward_access: The reward belongs to the key's tenant (claims and referrals inherit it).
CREATE OR REPLACE FUNCTION app_api_key_reward_access("rewardId" text) RETURNS boolean
LANGUAGE sql STABLE SECURITY DEFINER SET search_path = public AS $$
  SELECT app_current_api_key_id() IS NOT NULL
    AND EXISTS (SELECT 1 FROM public."Reward" r WHERE r.id = "rewardId" AND app_api_key_org_access(r."tenantId"));
$$;

-- app_api_key_signup_referee_access: The referee of a signup referral was just redeemed for at the key's store (ADR 035). SECURITY DEFINER so the lookup does not depend on the redemption table's own policies.
CREATE OR REPLACE FUNCTION app_api_key_signup_referee_access("refereeUserId" text) RETURNS boolean
LANGUAGE sql STABLE SECURITY DEFINER SET search_path = public AS $$
  SELECT app_current_api_key_id() IS NOT NULL
    AND EXISTS (
      SELECT 1 FROM public."RewardRedemption" rr
      WHERE rr."userId" = "refereeUserId"
        AND rr."isDeleted" = false
        AND app_api_key_store_access(rr."tenantId", rr."locationId")
    );
$$;

-- app_api_key_customer_access: The user is a customer of the API key's tenant (ADR 085: the till records the customer's tier). SECURITY DEFINER so the lookup does not depend on TenantCustomer's own policies.
CREATE OR REPLACE FUNCTION app_api_key_customer_access("customerUserId" text) RETURNS boolean
LANGUAGE sql STABLE SECURITY DEFINER SET search_path = public AS $$
  SELECT app_current_api_key_id() IS NOT NULL
    AND EXISTS (
      SELECT 1 FROM public."TenantCustomer" tc
      WHERE tc."userId" = "customerUserId"
        AND tc."isDeleted" = false
        AND app_api_key_org_access(tc."tenantId")
    );
$$;

-- app_stamp_authorization_change: Stamps User.authorizationChangedAt (database clock) whenever tokenVersion, isActive or isDeleted change: the durable backstop every API instance sweeps to drop cached authorization an after-commit invalidation missed.
CREATE OR REPLACE FUNCTION app_stamp_authorization_change() RETURNS trigger
LANGUAGE plpgsql AS $$
BEGIN
  IF NEW."tokenVersion" IS DISTINCT FROM OLD."tokenVersion"
     OR NEW."isActive" IS DISTINCT FROM OLD."isActive"
     OR NEW."isDeleted" IS DISTINCT FROM OLD."isDeleted" THEN
    NEW."authorizationChangedAt" := (extract(epoch FROM clock_timestamp()) * 1000)::bigint;
  END IF;
  RETURN NEW;
END;
$$;

-- audit_trail_notify: `NOTIFY audit_trail` with only the table name (never a row's content), so the admin audit log updates live; delivered on commit.
CREATE OR REPLACE FUNCTION public.audit_trail_notify() RETURNS trigger
  LANGUAGE plpgsql
  AS $$
BEGIN
  PERFORM pg_notify('audit_trail', TG_TABLE_NAME);
  RETURN NULL;
END
$$;

-- app_purge_audit_batch: One batch of retention. `affected`: rows deleted (or, dry, eligible); `held`: rows past the cutoff an active legal hold keeps (counted on a dry run only).
CREATE OR REPLACE FUNCTION public.app_purge_audit_batch(target text, cutoff bigint, batch_size integer, dry_run boolean)
RETURNS TABLE (affected bigint, held bigint)
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = pg_catalog
AS $$
DECLARE
  -- = RECORD_RETENTION_DAYS (src/platform/domain/record-retention.ts).
  retention_days CONSTANT integer := 3653;
  max_batch CONSTANT integer := 10000;
  ms_per_day CONSTANT bigint := 86400000;
  newest_allowed bigint := (extract(epoch FROM clock_timestamp()) * 1000)::bigint - retention_days::bigint * ms_per_day;
BEGIN
  IF public.app_system_operation() IS DISTINCT FROM 'maintenance.audit_record_retention' THEN
    RAISE EXCEPTION 'app_purge_audit_batch runs only under the maintenance.audit_record_retention system operation'
      USING ERRCODE = 'insufficient_privilege';
  END IF;
  IF cutoff IS NULL OR cutoff > newest_allowed THEN
    RAISE EXCEPTION 'retention cutoff % is newer than the % day retention allows (%)', cutoff, retention_days, newest_allowed
      USING ERRCODE = 'check_violation';
  END IF;
  IF batch_size IS NULL OR batch_size < 1 OR batch_size > max_batch THEN
    RAISE EXCEPTION 'retention batch size must be 1..%', max_batch USING ERRCODE = 'invalid_parameter_value';
  END IF;

  IF target = 'AUDIT_LOG' THEN
    IF dry_run THEN
      RETURN QUERY
        SELECT
          count(*) FILTER (WHERE NOT on_hold),
          count(*) FILTER (WHERE on_hold)
        FROM (
          SELECT EXISTS (
            SELECT 1 FROM public."AuditLegalHold" h
            WHERE h."liftedAt" IS NULL AND h."isDeleted" = false
              AND (h."tenantId" IS NOT NULL OR h."userId" IS NOT NULL)
              AND (h."tenantId" IS NULL OR h."tenantId" = r."tenantId")
              AND (h."userId" IS NULL OR h."userId" = r."actorUserId")
          ) AS on_hold
          FROM public."AuditLog" r WHERE r."occurredAt" < cutoff
        ) AS rows;
      RETURN;
    END IF;
    RETURN QUERY
      WITH doomed AS (
        SELECT r.id FROM public."AuditLog" r
        WHERE r."occurredAt" < cutoff
          AND NOT EXISTS (
            SELECT 1 FROM public."AuditLegalHold" h
            WHERE h."liftedAt" IS NULL AND h."isDeleted" = false
              AND (h."tenantId" IS NOT NULL OR h."userId" IS NOT NULL)
              AND (h."tenantId" IS NULL OR h."tenantId" = r."tenantId")
              AND (h."userId" IS NULL OR h."userId" = r."actorUserId")
          )
        ORDER BY r."occurredAt"
        LIMIT batch_size
      ), deleted AS (
        DELETE FROM public."AuditLog" r USING doomed d WHERE r.id = d.id RETURNING 1
      )
      SELECT count(*)::bigint, 0::bigint FROM deleted;
    RETURN;
  END IF;

  IF target = 'DATA_CHANGE_LOG' THEN
    IF dry_run THEN
      RETURN QUERY
        SELECT
          count(*) FILTER (WHERE NOT on_hold),
          count(*) FILTER (WHERE on_hold)
        FROM (
          SELECT EXISTS (
            SELECT 1 FROM public."AuditLegalHold" h
            WHERE h."liftedAt" IS NULL AND h."isDeleted" = false
              AND (h."tenantId" IS NOT NULL OR h."userId" IS NOT NULL)
              AND (h."tenantId" IS NULL OR h."tenantId" = r."tenantId")
              AND (h."userId" IS NULL OR h."userId" = r."actorUserId")
          ) AS on_hold
          FROM public."DataChangeLog" r WHERE r."occurredAt" < cutoff
        ) AS rows;
      RETURN;
    END IF;
    RETURN QUERY
      WITH doomed AS (
        SELECT r.id, r."correlationId" FROM public."DataChangeLog" r
        WHERE r."occurredAt" < cutoff
          AND NOT EXISTS (
            SELECT 1 FROM public."AuditLegalHold" h
            WHERE h."liftedAt" IS NULL AND h."isDeleted" = false
              AND (h."tenantId" IS NOT NULL OR h."userId" IS NOT NULL)
              AND (h."tenantId" IS NULL OR h."tenantId" = r."tenantId")
              AND (h."userId" IS NULL OR h."userId" = r."actorUserId")
          )
        ORDER BY r."occurredAt"
        LIMIT batch_size
      ), deleted AS (
        DELETE FROM public."DataChangeLog" r USING doomed d WHERE r.id = d.id RETURNING r."correlationId"
      ), emptied_groups AS (
        -- A group whose changes are all gone has nothing left to index.
        DELETE FROM public."DataChangeGroup" g
        WHERE g."correlationId" IN (SELECT DISTINCT "correlationId" FROM deleted)
          AND NOT EXISTS (
            SELECT 1 FROM public."DataChangeLog" l
            WHERE l."correlationId" = g."correlationId"
              AND l.id NOT IN (SELECT id FROM doomed)
          )
        RETURNING 1
      )
      SELECT (SELECT count(*) FROM deleted)::bigint, 0::bigint;
    RETURN;
  END IF;

  RAISE EXCEPTION 'unknown retention target %', target USING ERRCODE = 'invalid_parameter_value';
END;
$$;
ALTER FUNCTION public.app_purge_audit_batch(text, bigint, integer, boolean) OWNER TO app_retention;

-- app_mask_personal_json: A JSON value with every personal field (by name) and every mention of the person's email replaced by "[erased]", at any depth. Pure.
CREATE OR REPLACE FUNCTION public.app_mask_personal_json(value jsonb, person_email text)
RETURNS jsonb
LANGUAGE plpgsql
IMMUTABLE
SET search_path = pg_catalog
AS $$
DECLARE
  personal_keys CONSTANT text[] := ARRAY[
    'email', 'fullName', 'phone', 'displayName', 'ipAddress', 'lastIpAddress', 'ip', 'userAgent',
    'deviceName', 'payerName', 'payerEmail', 'contactPhone', 'contactEmail', 'passwordHash', 'refereeIp'
  ];
  result jsonb;
  item record;
BEGIN
  IF value IS NULL THEN
    RETURN NULL;
  END IF;
  CASE jsonb_typeof(value)
    WHEN 'object' THEN
      result := '{}'::jsonb;
      FOR item IN SELECT key, entry FROM jsonb_each(value) AS e(key, entry) LOOP
        IF item.key = ANY (personal_keys) AND jsonb_typeof(item.entry) <> 'null' THEN
          result := result || jsonb_build_object(item.key, '[erased]');
        ELSE
          result := result || jsonb_build_object(item.key, public.app_mask_personal_json(item.entry, person_email));
        END IF;
      END LOOP;
      RETURN result;
    WHEN 'array' THEN
      SELECT coalesce(jsonb_agg(public.app_mask_personal_json(element, person_email)), '[]'::jsonb) INTO result FROM jsonb_array_elements(value) AS a(element);
      RETURN result;
    WHEN 'string' THEN
      IF person_email IS NOT NULL AND position(lower(person_email) IN lower(value #>> '{}')) > 0 THEN
        RETURN to_jsonb('[erased]'::text);
      END IF;
      RETURN value;
    ELSE
      RETURN value;
  END CASE;
END;
$$;

-- app_mask_erased_person: Masks the person in every kept record; returns how many rows changed.
CREATE OR REPLACE FUNCTION public.app_mask_erased_person(person_id text, person_email text)
RETURNS bigint
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = pg_catalog
AS $$
DECLARE
  masked bigint := 0;
  changed bigint;
  now_ms bigint := (extract(epoch FROM clock_timestamp()) * 1000)::bigint;
  erased constant text := '[erased]';
BEGIN
  IF public.app_system_operation() IS DISTINCT FROM 'privacy.account.erase' THEN
    RAISE EXCEPTION 'app_mask_erased_person runs only under the privacy.account.erase system operation'
      USING ERRCODE = 'insufficient_privilege';
  END IF;
  IF NOT EXISTS (
    SELECT 1 FROM public."AccountErasure" e
    WHERE e."userId" = person_id AND e.status = 'PENDING' AND e."isDeleted" = false AND e."scheduledFor" <= now_ms
  ) THEN
    RAISE EXCEPTION 'no due erasure for %', person_id USING ERRCODE = 'check_violation';
  END IF;

  UPDATE public."AuditLog" r SET
    "ipAddress" = NULL, "userAgent" = NULL, "browserName" = NULL, "osName" = NULL,
    "requestHeaders" = public.app_mask_personal_json(r."requestHeaders", person_email),
    "requestParams" = public.app_mask_personal_json(r."requestParams", person_email),
    "requestBody" = public.app_mask_personal_json(r."requestBody", person_email),
    "responseBody" = public.app_mask_personal_json(r."responseBody", person_email),
    "errorDetail" = public.app_mask_personal_json(r."errorDetail", person_email)
  WHERE r."actorUserId" = person_id OR r."impersonatorUserId" = person_id
     OR position(lower(person_email) IN lower(coalesce(r."requestBody"::text, '') || coalesce(r."responseBody"::text, ''))) > 0;
  GET DIAGNOSTICS changed = ROW_COUNT; masked := masked + changed;

  UPDATE public."DataChangeLog" r SET
    "oldData" = public.app_mask_personal_json(r."oldData", person_email),
    "newData" = public.app_mask_personal_json(r."newData", person_email)
  WHERE (r."tableName" = 'User' AND r."rowId" = person_id)
     OR r."actorUserId" = person_id
     OR r."oldData" ->> 'userId' = person_id OR r."newData" ->> 'userId' = person_id
     OR position(lower(person_email) IN lower(coalesce(r."oldData"::text, '') || coalesce(r."newData"::text, ''))) > 0;
  GET DIAGNOSTICS changed = ROW_COUNT; masked := masked + changed;

  UPDATE public."MarketingConsent" SET ip = NULL, "userAgent" = NULL WHERE "userId" = person_id;
  GET DIAGNOSTICS changed = ROW_COUNT; masked := masked + changed;
  UPDATE public."ImpersonationAuditLog" SET "ipAddress" = NULL, "userAgent" = NULL WHERE "targetUserId" = person_id;
  GET DIAGNOSTICS changed = ROW_COUNT; masked := masked + changed;
  UPDATE public."ImpersonationSession" SET "ipAddress" = NULL, "userAgent" = NULL WHERE "targetUserId" = person_id;
  GET DIAGNOSTICS changed = ROW_COUNT; masked := masked + changed;
  UPDATE public."MfaRecoveryAuditLog" SET "ipAddress" = NULL, "userAgent" = NULL WHERE "subjectUserId" = person_id OR "actorUserId" = person_id;
  GET DIAGNOSTICS changed = ROW_COUNT; masked := masked + changed;
  UPDATE public."AuthorizationAudit" r SET "ipAddress" = NULL, "userAgent" = NULL, evaluation = public.app_mask_personal_json(r.evaluation, person_email)
  WHERE r."actorId" = person_id;
  GET DIAGNOSTICS changed = ROW_COUNT; masked := masked + changed;
  UPDATE public."EmailLog" r SET "to" = erased, metadata = public.app_mask_personal_json(r.metadata, person_email)
  WHERE lower(r."to") = lower(person_email);
  GET DIAGNOSTICS changed = ROW_COUNT; masked := masked + changed;
  UPDATE public."Notification" r SET "recipientKey" = erased, payload = public.app_mask_personal_json(r.payload, person_email)
  WHERE r."recipientUserId" = person_id;
  GET DIAGNOSTICS changed = ROW_COUNT; masked := masked + changed;

  RETURN masked;
END;
$$;
ALTER FUNCTION public.app_mask_erased_person(text, text) OWNER TO app_erasure;
